style.css:
[class~="o-tab-btn--infinity"]::before,
[class~="o-tab-btn--infinity o-tab-btn--active"]::before,
[class~="o-tab-btn--eternity"]::before,
[class~="o-tab-btn--eternity o-tab-btn--eternity"]::before {
  content:' ';
  display: block; 
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  background-image: url('https://cdn.discordapp.com/attachments/884177792613371924/1561994364228472862/image.png?ex=6ad8601c&is=6ad70e9c&hm=68e9f27d68102f9f8fd1357b4c5dd20931b84b5e2c0bb866dcdcee980be562f4&');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  opacity: 0.25;
}

[class~="o-tab-btn--infinity"],
[class~="o-tab-btn--infinity o-tab-btn--active"],
[class~="o-tab-btn--eternity"],
[class~="o-tab-btn--eternity o-tab-btn--eternity"] {
  background-image: url('https://cdn.discordapp.com/attachments/884177792613371924/1561994364228472862/image.png?ex=6ad8601c&is=6ad70e9c&hm=68e9f27d68102f9f8fd1357b4c5dd20931b84b5e2c0bb866dcdcee980be562f4&');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
}

